+++ b/applets/taskmanager/main.xml
@@ -27,7 +27,7 @@
       <default>true</default>
     </entry>
     <entry name="groupingStrategy" type="Enum">
-      <label>How tasks are grouped: 0 = Do Not Group, 1 = By Program Name</label>
+      <label>How tasks are grouped: 0 = Manually, 1 = By Program Name</label>
       <default>1</default>
     </entry>
     <entry name="groupedTaskVisualization" type="Enum">
@@ -50,6 +50,14 @@
       <label>The launcher URLs (usually .desktop file or executable URLs) of applications that should not have their tasks grouped.</label>
       <default></default>
     </entry>
+    <entry name="groupingAppIdAllowlist" type="StringList">
+      <label>The id's (usually .desktop file names) of applications that should have their tasks grouped when grouping manually.</label>
+      <default></default>
+    </entry>
+    <entry name="groupingLauncherUrlAllowlist" type="StringList">
+      <label>The launcher URLs (usually .desktop file or executable URLs) of applications that should have their tasks grouped when grouping manually.</label>
+      <default></default>
+    </entry>
     <entry name="sortingStrategy" type="Int">
       <label>Values from TaskManager::TasksModel::SortMode</label>
       <default>1</default>
