From e8b0ca8959c087ed9cf7a78e4b3fdc095f3d1218 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 17:55:11 +0100
Subject: [PATCH] libtaskmanager: add a manual group mode with an allowlist

With grouping disabled there was no way to group just a few programs,
so the new GroupManually mode groups only the apps on a new allowlist,
which requestToggleGrouping() fills in and empties in that mode.

BUG: 434700
---
 libtaskmanager/taskgroupingproxymodel.cpp | 104 ++++++++++++++++++++--
 libtaskmanager/taskgroupingproxymodel.h   |  57 +++++++++++-
 libtaskmanager/tasksmodel.cpp             |  34 +++++++
 libtaskmanager/tasksmodel.h               |  58 ++++++++++++
 4 files changed, 246 insertions(+), 7 deletions(-)

diff --git a/libtaskmanager/taskgroupingproxymodel.cpp b/libtaskmanager/taskgroupingproxymodel.cpp
index 82709a40c9..21af4bd092 100644
--- a/libtaskmanager/taskgroupingproxymodel.cpp
+++ b/libtaskmanager/taskgroupingproxymodel.cpp
@@ -31,6 +31,9 @@ public:
     QSet<QString> blacklistedAppIds;
     QSet<QString> blacklistedLauncherUrls;

+    QSet<QString> allowlistedAppIds;
+    QSet<QString> allowlistedLauncherUrls;
+
     bool isGroup(int row);
     bool any(const QModelIndex &parent, int role);
     bool all(const QModelIndex &parent, int role);
@@ -50,6 +53,8 @@ public:
     bool shouldGroupTasks();
     void checkGrouping(bool silent = false);
     bool isBlacklisted(const QModelIndex &sourceIndex);
+    bool isAllowlisted(const QModelIndex &sourceIndex);
+    bool isGroupingAllowed(const QModelIndex &sourceIndex);
     bool tryToGroup(const QModelIndex &sourceIndex, bool silent = false);
     void formGroupFor(const QModelIndex &index);
     void breakGroupFor(const QModelIndex &index, bool silent = false);
@@ -287,6 +292,10 @@ bool TaskGroupingProxyModel::Private::shouldGroupTasks()
         return false;
     }

+    if (groupMode == TasksModel::GroupManually) {
+        return true;
+    }
+
     if (windowTasksThreshold != -1) {
         // We're going to check the number of window tasks in the source model
         // against the grouping threshold. In practice that means we're ignoring
@@ -315,6 +324,10 @@ void TaskGroupingProxyModel::Private::checkGrouping(bool silent)
     if (shouldGroupTasks()) {
         for (int i = (rowMap.count()) - 1; i >= 0; --i) {
             if (isGroup(i)) {
+                if (!isGroupingAllowed(q->sourceModel()->index(rowMap.at(i)->constFirst(), 0))) {
+                    breakGroupFor(q->index(i, 0), silent);
+                }
+
                 continue;
             }

@@ -355,6 +368,33 @@ bool TaskGroupingProxyModel::Private::isBlacklisted(const QModelIndex &sourceInd
     return false;
 }

+bool TaskGroupingProxyModel::Private::isAllowlisted(const QModelIndex &sourceIndex)
+{
+    if (allowlistedAppIds.contains(sourceIndex.data(AbstractTasksModel::AppId).toString())) {
+        return true;
+    }
+
+    if (allowlistedLauncherUrls.count()) {
+        const QUrl &launcherUrl = sourceIndex.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl();
+        const QString &launcherUrlString = launcherUrl.toString(QUrl::PrettyDecoded | QUrl::RemoveQuery);
+
+        if (allowlistedLauncherUrls.contains(launcherUrlString)) {
+            return true;
+        }
+    }
+
+    return false;
+}
+
+bool TaskGroupingProxyModel::Private::isGroupingAllowed(const QModelIndex &sourceIndex)
+{
+    if (groupMode == TasksModel::GroupManually) {
+        return isAllowlisted(sourceIndex);
+    }
+
+    return !isBlacklisted(sourceIndex);
+}
+
 bool TaskGroupingProxyModel::Private::tryToGroup(const QModelIndex &sourceIndex, bool silent)
 {
     // NOTE: We only group window tasks at this time. If this ever changes, the
@@ -372,8 +412,8 @@ bool TaskGroupingProxyModel::Private::tryToGroup(const QModelIndex &sourceIndex,
         return false;
     }

-    // Blacklist checks.
-    if (isBlacklisted(sourceIndex)) {
+    // Blacklist and allowlist checks.
+    if (!isGroupingAllowed(sourceIndex)) {
         return false;
     }

@@ -651,7 +691,7 @@ QVariant TaskGroupingProxyModel::data(const QModelIndex &proxyIndex, int role) c
     }

     if (role == AbstractTasksModel::IsGroupable) {
-        return !d->isBlacklisted(sourceIndex);
+        return d->isGroupingAllowed(sourceIndex);
     }

     if (isWindowGroup) {
@@ -935,6 +975,43 @@ void TaskGroupingProxyModel::setBlacklistedLauncherUrls(const QStringList &list)
     }
 }

+QStringList TaskGroupingProxyModel::allowlistedAppIds() const
+{
+    return d->allowlistedAppIds.values();
+}
+
+void TaskGroupingProxyModel::setAllowlistedAppIds(const QStringList &list)
+{
+    const QSet<QString> &set = QSet<QString>(list.cbegin(), list.cend());
+
+    if (d->allowlistedAppIds != set) {
+        d->allowlistedAppIds = set;
+
+        // checkGrouping() forms and breaks apart groups as needed under the changed allowlist.
+        d->checkGrouping();
+
+        Q_EMIT allowlistedAppIdsChanged();
+    }
+}
+
+QStringList TaskGroupingProxyModel::allowlistedLauncherUrls() const
+{
+    return d->allowlistedLauncherUrls.values();
+}
+
+void TaskGroupingProxyModel::setAllowlistedLauncherUrls(const QStringList &list)
+{
+    const QSet<QString> &set = QSet<QString>(list.cbegin(), list.cend());
+
+    if (d->allowlistedLauncherUrls != set) {
+        d->allowlistedLauncherUrls = set;
+
+        d->checkGrouping();
+
+        Q_EMIT allowlistedLauncherUrlsChanged();
+    }
+}
+
 void TaskGroupingProxyModel::requestActivate(const QModelIndex &index)
 {
     if (!d->abstractTasksSourceModel || !index.isValid() || index.model() != this) {
@@ -1274,7 +1351,17 @@ void TaskGroupingProxyModel::requestToggleGrouping(const QModelIndex &index)
     const QUrl &launcherUrl = index.data(AbstractTasksModel::LauncherUrlWithoutIcon).toUrl();
     const QString &launcherUrlString = launcherUrl.toString(QUrl::RemoveQuery);

-    if (d->blacklistedAppIds.contains(appId) || d->blacklistedLauncherUrls.contains(launcherUrlString)) {
+    if (d->groupMode == TasksModel::GroupManually) {
+        if (d->allowlistedAppIds.contains(appId) || d->allowlistedLauncherUrls.contains(launcherUrlString)) {
+            d->allowlistedAppIds.remove(appId);
+            d->allowlistedLauncherUrls.remove(launcherUrlString);
+            d->breakGroupFor(index.parent().isValid() ? index.parent() : index);
+        } else {
+            d->allowlistedAppIds.insert(appId);
+            d->allowlistedLauncherUrls.insert(launcherUrlString);
+            d->formGroupFor(index.parent().isValid() ? index.parent() : index);
+        }
+    } else if (d->blacklistedAppIds.contains(appId) || d->blacklistedLauncherUrls.contains(launcherUrlString)) {
         d->blacklistedAppIds.remove(appId);
         d->blacklistedLauncherUrls.remove(launcherUrlString);

@@ -1304,8 +1391,13 @@ void TaskGroupingProxyModel::requestToggleGrouping(const QModelIndex &index)
         }
     }

-    Q_EMIT blacklistedAppIdsChanged();
-    Q_EMIT blacklistedLauncherUrlsChanged();
+    if (d->groupMode == TasksModel::GroupManually) {
+        Q_EMIT allowlistedAppIdsChanged();
+        Q_EMIT allowlistedLauncherUrlsChanged();
+    } else {
+        Q_EMIT blacklistedAppIdsChanged();
+        Q_EMIT blacklistedLauncherUrlsChanged();
+    }
 }

 }
